/**
 * A single source reference associated with a `Citation`. Each `CitationSource`
 * in `Citation.sources` corresponds to one page/view in the citation's own
 * paginated resource details popover.
 */
export interface CitationSource {
    /**
     * The title of the source document or web page.
     */
    title?: string;
    /**
     * A short description or excerpt of the source.
     */
    description?: string;
    /**
     * The full URL of the source.
     */
    url?: string;
}
